import React, { useState } from "react";
import { motion } from "framer-motion";
import axios from "axios";
import { UploadCloud, CheckCircle2, XCircle } from "lucide-react";

const Interview = () => {
  const [video, setVideo] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [status, setStatus] = useState(""); // success / error
  const [message, setMessage] = useState("");

  const handleFileChange = (e) => {
    setVideo(e.target.files[0]);
    setStatus("");
    setMessage("");
  };

  const handleUpload = async () => {
    if (!video) {
      setMessage("Please select a video first!");
      setStatus("error");
      return;
    }

    const formData = new FormData();
    formData.append("file", video);

    try {
      setUploading(true);
      const res = await axios.post("http://localhost:8080/api/video/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      setStatus("success");
      setMessage("✅ Video uploaded successfully!");
    } catch (err) {
      console.error(err);
      setStatus("error");
      setMessage("❌ Upload failed!");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] bg-gradient-to-br from-blue-50 to-blue-100 px-6 py-10">
      <motion.div
        initial={{ opacity: 0, y: -30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="text-center mb-10"
      >
        <h1 className="text-4xl font-bold text-gray-800 mb-2">🎥 AI Interview Upload</h1>
        <p className="text-gray-600">Upload your interview video to receive smart AI feedback.</p>
      </motion.div>

      <motion.div
        whileHover={{ scale: 1.03 }}
        className="bg-white shadow-2xl rounded-2xl p-10 w-full max-w-md text-center border border-gray-100 transition-all duration-300"
      >
        <div className="flex flex-col items-center">
          <div className="p-6 bg-blue-50 rounded-full mb-4">
            <UploadCloud className="w-10 h-10 text-blue-600" />
          </div>

          <input
            type="file"
            accept="video/*"
            onChange={handleFileChange}
            className="mb-5 text-sm text-gray-600 border border-gray-300 rounded-md cursor-pointer px-4 py-2 w-full"
          />

          <motion.button
            whileTap={{ scale: 0.95 }}
            onClick={handleUpload}
            disabled={uploading}
            className={`px-8 py-3 rounded-md font-semibold text-white w-full transition-all duration-300 ${
              uploading ? "bg-blue-400 cursor-not-allowed" : "bg-blue-600 hover:bg-blue-700"
            }`}
          >
            {uploading ? "Uploading..." : "Upload Video"}
          </motion.button>

          {message && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className={`mt-6 flex items-center justify-center gap-2 text-lg ${
                status === "success" ? "text-green-600" : "text-red-600"
              }`}
            >
              {status === "success" && <CheckCircle2 className="w-6 h-6" />}
              {status === "error" && <XCircle className="w-6 h-6" />}
              <span>{message}</span>
            </motion.div>
          )}
        </div>
      </motion.div>

      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.2 }}
        className="mt-10 text-gray-500 text-sm"
      >
        <p>⚠️ Max file size: 200MB | Accepted: MP4, MOV, AVI</p>
      </motion.div>
    </div>
  );
};

export default Interview;
